package com.nexo.presentation.screen.settings

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The inventory asset is generated by Gradle, but the parser in the APK is what
 * decides whether a reader ever sees the licence column. Its tolerance matters
 * as much as its happy path: a build that ships one malformed line must lose
 * that line, not the whole page.
 */
class LicensesInventoryTest {
    @Test
    fun parsesCoordinateAndLicenceId() {
        val notices = parseThirdPartyNotices("androidx.core:core:1.13.1\tApache-2.0")

        assertEquals(1, notices.size)
        assertEquals("androidx.core", notices.single().group)
        assertEquals("core", notices.single().name)
        assertEquals("1.13.1", notices.single().version)
        assertEquals("Apache-2.0", notices.single().licenseId)
    }

    @Test
    fun keepsAVersionThatContainsAColon() {
        val notices = parseThirdPartyNotices("com.example:lib:1.0:alpha\tMIT")

        assertEquals("1.0:alpha", notices.single().version)
        assertEquals("MIT", notices.single().licenseId)
    }

    @Test
    fun dropsLegacyLinesWithoutTheLicenceColumn() {
        // A line with no tab cannot say whether the licence is absent or lost, so
        // it is dropped instead of being labelled NOT_DECLARED by assumption.
        assertTrue(parseThirdPartyNotices("androidx.core:core:1.13.1").isEmpty())
        assertTrue(parseThirdPartyNotices("androidx.core:core:1.13.1\t").isEmpty())
    }

    @Test
    fun dropsMalformedLinesInsteadOfThrowing() {
        val raw =
            """
            # header comment
            not-a-coordinate	MIT

            androidx.core:core:1.13.1	Apache-2.0
            only:two	MIT
            """.trimIndent()

        val notices = parseThirdPartyNotices(raw)

        assertEquals(1, notices.size)
        assertEquals("core", notices.single().name)
    }

    @Test
    fun collapsesDuplicateCoordinates() {
        val notices =
            parseThirdPartyNotices(
                "androidx.core:core:1.13.1\tApache-2.0\nandroidx.core:core:1.13.1\tApache-2.0",
            )

        assertEquals(1, notices.size)
    }

    @Test
    fun groupsByLicenceInDeclaredOrder() {
        val notices =
            parseThirdPartyNotices(
                """
                z.group:zlib:1.0	NOT_DECLARED
                androidx.core:core:1.13.1	Apache-2.0
                com.example:thing:2.0	MIT
                a.group:another:1.0	MIT
                """.trimIndent(),
            )

        val groups = groupNoticesByLicense(notices)

        assertEquals(listOf("Apache-2.0", "MIT", "NOT_DECLARED"), groups.map { it.id })
        assertEquals(2, groups.first { it.id == "MIT" }.notices.size)
        // Inside a section, ordering stays by coordinate so a version bump does
        // not reshuffle the list.
        assertEquals(
            "a.group",
            groups
                .first { it.id == "MIT" }
                .notices
                .first()
                .group,
        )
    }

    @Test
    fun notDeclaredBucketIsKeptAndExplained() {
        val groups = groupNoticesByLicense(parseThirdPartyNotices("com.google.guava:guava:33.3.1-android\tNOT_DECLARED"))

        val notDeclared = groups.single()
        assertEquals("NOT_DECLARED", notDeclared.id)
        assertEquals(null, notDeclared.textResource)
        assertEquals(com.nexo.feature.settings.R.string.licenses_not_declared_note, notDeclared.noteResource)
    }

    @Test
    fun licencesWithBundledTextPointAtTheirRawResource() {
        val groups =
            groupNoticesByLicense(
                parseThirdPartyNotices(
                    """
                    androidx.core:core:1.13.1	Apache-2.0
                    com.example:thing:2.0	MIT
                    org.example:bsd:3.0	BSD-3-Clause
                    """.trimIndent(),
                ),
            )

        assertEquals(
            listOf(
                com.nexo.feature.settings.R.raw.license_apache_2_0,
                com.nexo.feature.settings.R.raw.license_mit,
                com.nexo.feature.settings.R.raw.license_bsd_3_clause,
            ),
            groups.map { it.textResource },
        )
    }

    @Test
    fun unknownLicenceSortsAfterTheKnownOnes() {
        val groups =
            groupNoticesByLicense(
                parseThirdPartyNotices(
                    """
                    com.example:weird:1.0	CUSTOM-LICENCE
                    androidx.core:core:1.13.1	Apache-2.0
                    """.trimIndent(),
                ),
            )

        assertEquals(listOf("Apache-2.0", "CUSTOM-LICENCE"), groups.map { it.id })
    }
}
